# Analyze connected components of 5s
from collections import deque

def find_connected_components(grid):
    h, w = grid.shape
    components = []
    visited = set()

    for i in range(h):
        for j in range(w):
            if grid[i, j] == 5 and (i, j) not in visited:
                component = []
                queue = deque([(i, j)])
                visited.add((i, j))

                while queue:
                    ci, cj = queue.popleft()
                    component.append((ci, cj))

                    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                        ni, nj = ci + di, cj + dj
                        if 0 <= ni < h and 0 <= nj < w and grid[ni, nj] == 5 and (ni, nj) not in visited:
                            visited.add((ni, nj))
                            queue.append((ni, nj))

                components.append(component)

    return components

